  }

  /** helper function to set the values of all input ports.
   * @param recovery_frame payload for data port recovery_frame
   * @param session_frame payload for data port session_frame
   * @param image_frame payload for data port image_frame
   */
  def put_concrete_inputs(recovery_frame : EIT_Acquisition_Supervisor.RecoveryFrame,
                          session_frame : EIT_Acquisition_Supervisor.SessionFrame,
                          image_frame : EIT_Acquisition_Supervisor.ImageFrame): Unit = {
    put_recovery_frame(recovery_frame)
    put_session_frame(session_frame)
    put_image_frame(image_frame)
  }


  /** helper function to check ImageReleaseFeasibilityOwner_acquisition_process_image_release_feasibility's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param release_proposal method that will be called with the value of the outgoing data
   *        port 'release_proposal'.
   */
  def check_concrete_output(release_proposal: EIT_Acquisition_Supervisor.Proposal.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val release_proposalValue: EIT_Acquisition_Supervisor.Proposal.Type = get_release_proposal().get
    if(!release_proposal(release_proposalValue)) {
      testFailures = testFailures :+ st"'release_proposal' did not match expected: value of the outgoing data port is ${release_proposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_recovery_frame(value : EIT_Acquisition_Supervisor.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_release_feasibility.operational_api.recovery_frame_Id, EIT_Acquisition_Supervisor.RecoveryFrame_Payload(value))
