  }

  // getter for out DataPort
  def get_release_proposal(): Option[EIT_Acquisition_Supervisor.Proposal.Type] = {
    val value: Option[EIT_Acquisition_Supervisor.Proposal.Type] = get_release_proposal_payload() match {
      case Some(EIT_Acquisition_Supervisor.Proposal_Payload(v)) => Some(v)
