      case _ => None[EIT_Acquisition_Supervisor.Proposal.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_release_proposal_payload(): Option[EIT_Acquisition_Supervisor.Proposal_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_release_feasibility.initialization_api.release_proposal_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.Proposal_Payload]]
